class Solution {
    vector<vector<int>> adj;
    int t, target;

    double dfs(int node, int parent, int time, double prob) {
        if (time == t) {
            return (node == target) ? prob : 0.0;
        }
        int children = 0;
        for (int nb : adj[node]) {
            if (nb != parent) children++;
        }
        if (children == 0) {
            return (node == target) ? prob : 0.0;
        }
        if (node == target) return 0.0;
        double result = 0.0;
        for (int nb : adj[node]) {
            if (nb != parent) {
                result += dfs(nb, node, time + 1, prob / children);
            }
        }
        return result;
    }

public:
    double frogPosition(int n, vector<vector<int>>& edges, int t, int target) {
        adj.assign(n + 1, {});
        this->t = t;
        this->target = target;
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        return dfs(1, -1, 0, 1.0);
    }
};
